-- Source: 002-driver-identity.sql; SHA256: c6cc109f4ffc5b3856e45a200edf40594e5ff14ad3ba1f1d5dad9c070e8a9c61
-- Does not enable driver login or assign regions to legacy records.
set local lock_timeout = '3s';
set local statement_timeout = '20s';

lock table public.profiles, public.drivers in access exclusive mode;
do $$
begin
  if to_regclass('public.regions') is null
     or to_regclass('public.driver_auth_links') is not null then
    raise exception 'Unexpected test schema; inspect before running';
  end if;
  if exists (select 1 from information_schema.columns
             where table_schema = 'public' and table_name = 'profiles'
               and column_name = 'account_type') then
    raise exception 'Identity expansion already present';
  end if;
end;
$$;

create temporary table driver_identity_before on commit drop as
select id, to_jsonb(p) as original from public.profiles p;

alter table public.profiles add column account_type text not null default 'pending'
  check (account_type in ('pending', 'staff', 'driver'));
update public.profiles set account_type = 'staff';

alter table public.drivers add constraint driver_identity_region_key unique (id, region_id);
alter table public.profiles add constraint driver_profile_identity_key
  unique (id, region_id, account_type, role);

create function public.is_staff()
returns boolean language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.profiles
    where id = (select auth.uid()) and account_type = 'staff'
  );
$$;
create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.profiles
    where id = (select auth.uid()) and account_type = 'staff' and role = 'admin'
  );
$$;
revoke all on function public.is_staff(), public.is_admin() from public, anon;
grant execute on function public.is_staff(), public.is_admin() to authenticated;

-- A restrictive gate ANDs with existing permissive policies, even if they use true.
-- This preserves the inspected legacy staff rules without granting drivers those rules.
do $$
declare target text;
begin
  foreach target in array array[
    'orders', 'drivers', 'vehicles', 'companies', 'order_sources',
    'vehicle_monthly_finances', 'balance_expense_items', 'driver_wage_items', 'invoice_counters', 'invoice_numbers'
  ] loop
    execute format(
      'create policy driver_identity_staff_gate on public.%I as restrictive for all to authenticated
       using ((select public.is_staff())) with check ((select public.is_staff()))', target
    );
  end loop;
end;
$$;

-- Existing self-profile SELECT stays available. Clients cannot promote themselves.
revoke insert, update, delete, truncate, references, trigger
  on public.profiles from public, anon, authenticated;

create table public.driver_auth_links (
  driver_id uuid primary key,
  user_id uuid not null unique references auth.users(id) on delete restrict,
  region_id uuid not null references public.regions(id) on delete restrict,
  account_type text not null default 'driver' check (account_type = 'driver'),
  profile_role text not null default 'user' check (profile_role = 'user'),
  status text not null default 'active' check (status in ('active', 'suspended', 'revoked')),
  linked_at timestamptz not null default now(),
  linked_by uuid not null references auth.users(id) on delete restrict,
  updated_at timestamptz not null default now(),
  updated_by uuid not null references auth.users(id) on delete restrict,
  version bigint not null default 1 check (version > 0),
  foreign key (driver_id, region_id)
    references public.drivers(id, region_id) on delete restrict,
  foreign key (user_id, region_id, account_type, profile_role)
    references public.profiles(id, region_id, account_type, role) on delete restrict
);
alter table public.driver_auth_links enable row level security;
revoke all on public.driver_auth_links from public, anon, authenticated;

create table public.driver_identity_audit (
  id uuid primary key default gen_random_uuid(),
  driver_id uuid not null references public.driver_auth_links(driver_id) on delete restrict,
  region_id uuid not null references public.regions(id) on delete restrict,
  actor_user_id uuid not null references auth.users(id) on delete restrict,
  event_type text not null check (event_type in ('linked', 'active', 'suspended', 'revoked')),
  version bigint not null,
  occurred_at timestamptz not null default now(),
  unique (driver_id, version)
);
alter table public.driver_identity_audit enable row level security;
revoke all on public.driver_identity_audit from public, anon, authenticated;

create function public.driver_identity_audit_change()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  if (select auth.uid()) is null then
    raise exception 'Authenticated actor required' using errcode = '42501';
  end if;
  insert into public.driver_identity_audit
    (driver_id, region_id, actor_user_id, event_type, version)
  values
    (new.driver_id, new.region_id, (select auth.uid()),
     case when tg_op = 'INSERT' then 'linked' else new.status end, new.version);
  return new;
end;
$$;
revoke all on function public.driver_identity_audit_change() from public, anon, authenticated;
create trigger audit_driver_identity after insert or update on public.driver_auth_links
  for each row execute function public.driver_identity_audit_change();

create function public.bind_driver_identity(target_user uuid, target_driver uuid)
returns void language plpgsql security definer set search_path = ''
as $$
declare
  actor uuid := (select auth.uid());
  driver_region uuid;
  target public.profiles%rowtype;
begin
  if not (select public.is_admin()) then
    raise exception 'Staff administrator required' using errcode = '42501';
  end if;
  if target_user = actor then
    raise exception 'Cannot bind your own administrator account' using errcode = '42501';
  end if;
  select * into target from public.profiles where id = target_user for update;
  if not found or target.account_type <> 'pending' or target.role <> 'user' then
    raise exception 'Binding requires an unprivileged pending profile' using errcode = '22023';
  end if;
  select region_id into driver_region from public.drivers where id = target_driver for update;
  if not found or driver_region is null then
    raise exception 'Driver must have a confirmed region' using errcode = '22023';
  end if;
  if target.region_id is not null and target.region_id <> driver_region then
    raise exception 'Profile and driver regions differ' using errcode = '22023';
  end if;
  update public.profiles set account_type = 'driver', region_id = driver_region
    where id = target_user;
  insert into public.driver_auth_links
    (driver_id, user_id, region_id, linked_by, updated_by)
  values (target_driver, target_user, driver_region, actor, actor);
end;
$$;

create function public.set_driver_identity_status(
  target_driver uuid, next_status text, expected_version bigint
)
returns bigint language plpgsql security definer set search_path = ''
as $$
declare
  link public.driver_auth_links%rowtype;
begin
  if not (select public.is_admin()) then
    raise exception 'Staff administrator required' using errcode = '42501';
  end if;
  if next_status is null or next_status not in ('active', 'suspended', 'revoked') then
    raise exception 'Invalid identity status' using errcode = '22023';
  end if;
  select * into link from public.driver_auth_links where driver_id = target_driver for update;
  if not found then
    raise exception 'Driver link not found' using errcode = '22023';
  end if;
  if expected_version is null or link.version <> expected_version then
    raise exception 'Identity version conflict' using errcode = '40001';
  end if;
  if link.status = 'revoked' then
    raise exception 'Revoked identities cannot be reactivated' using errcode = '22023';
  end if;
  if link.status = next_status then return link.version; end if;
  update public.driver_auth_links
    set status = next_status, version = version + 1,
        updated_at = now(), updated_by = (select auth.uid())
    where driver_id = target_driver
    returning version into link.version;
  return link.version;
end;
$$;

create function public.driver_identity()
returns table (driver_id uuid, region_id uuid, driver_name text, version bigint)
language sql stable security definer set search_path = ''
as $$
  select l.driver_id, l.region_id, d.name, l.version
  from public.driver_auth_links l
  join public.profiles p on p.id = l.user_id and p.region_id = l.region_id
  join public.drivers d on d.id = l.driver_id and d.region_id = l.region_id
  where l.user_id = (select auth.uid()) and l.status = 'active'
    and p.account_type = 'driver' and p.role = 'user';
$$;

revoke all on function public.bind_driver_identity(uuid, uuid),
  public.set_driver_identity_status(uuid, text, bigint), public.driver_identity()
  from public, anon;
grant execute on function public.bind_driver_identity(uuid, uuid),
  public.set_driver_identity_status(uuid, text, bigint), public.driver_identity()
  to authenticated;

do $$
begin
  if exists (
    select 1 from driver_identity_before b
    full join public.profiles p using (id)
    where b.original is distinct from (to_jsonb(p) - 'account_type')
  ) then
    raise exception 'Legacy profile preservation failed';
  end if;
end;
$$;
select 'driver_identity_prepared' as result,
       (select count(*) from driver_identity_before) as preserved_profiles,
       (select count(*) from public.driver_auth_links) as driver_links;


-- Source: 003-driver-trips.sql; SHA256: e10540a53ca07d8bad7c5a623bb3c9e5a79c25fbd8282b6bdd3f23d1e8bc3227
set local lock_timeout = '3s';
set local statement_timeout = '20s';

do $$
begin
  if to_regclass('public.driver_auth_links') is null
     or to_regclass('public.driver_assignments') is not null then
    raise exception 'Unexpected test identity schema';
  end if;
end;
$$;
alter table public.orders add constraint driver_order_region_key unique (id, region_id);
create table public.driver_assignments (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null,
  driver_id uuid not null,
  region_id uuid not null references public.regions(id) on delete restrict,
  service_date date not null,
  status text not null default 'assigned' check (status in ('assigned','acknowledged','revoked')),
  version bigint not null default 1 check (version > 0),
  created_at timestamptz not null default now(),
  created_by uuid not null references auth.users(id) on delete restrict,
  acknowledged_at timestamptz,
  revoked_at timestamptz,
  foreign key (order_id, region_id) references public.orders(id, region_id) on delete restrict,
  foreign key (driver_id, region_id) references public.drivers(id, region_id) on delete restrict
);
create unique index driver_assignment_active_day on public.driver_assignments(order_id,service_date)
  where status <> 'revoked';
create index driver_assignment_own_date on public.driver_assignments(driver_id,service_date,id);
create table public.driver_assignment_events (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null references public.driver_assignments(id) on delete restrict,
  actor_user_id uuid references auth.users(id) on delete restrict,
  event_type text not null check (event_type in ('acknowledged','revoked')),
  request_id uuid,
  occurred_at timestamptz not null default now(),
  unique (actor_user_id, request_id)
);
alter table public.driver_assignments enable row level security;
alter table public.driver_assignment_events enable row level security;
revoke all on public.driver_assignments,public.driver_assignment_events from public,anon,authenticated;

create function public.dispatch_test_driver_order(
  target_order uuid, target_driver uuid, target_date date
) returns uuid language plpgsql security definer set search_path = ''
as $$
declare
  item public.orders%rowtype;
  link public.driver_auth_links%rowtype;
  result uuid;
begin
  if not (select public.is_admin()) then
    raise exception 'Staff administrator required' using errcode = '42501';
  end if;
  select * into item from public.orders where id = target_order for update;
  if not found or item.region_id is null or target_date is null
     or target_date < item.date or target_date > item.end_date
     or target_date = any(item.off_dates) or item.status = 'キャンセル' then
    raise exception 'Order has no eligible service day' using errcode = '22023';
  end if;
  select * into link from public.driver_auth_links where driver_id = target_driver for share;
  if not found or link.status <> 'active' or link.region_id <> item.region_id then
    raise exception 'Active same-region driver required' using errcode = '22023';
  end if;
  insert into public.driver_assignments(order_id,driver_id,region_id,service_date,created_by)
    values(target_order,target_driver,item.region_id,target_date,(select auth.uid()))
    returning id into result;
  return result;
end;
$$;

-- Conservative test safety: ANY order edit revokes existing assignments in the same transaction.
-- Production needs explicit atomic split/reassignment, not this test-only invalidation rule.
create function public.revoke_test_order_assignments()
returns trigger language plpgsql security definer set search_path = ''
as $$
declare changed record;
begin
  for changed in
    update public.driver_assignments set status='revoked',version=version+1,revoked_at=now()
    where order_id=old.id and status <> 'revoked' returning id
  loop
    insert into public.driver_assignment_events(assignment_id,actor_user_id,event_type)
      values(changed.id,(select auth.uid()),'revoked');
  end loop;
  return new;
end;
$$;
create trigger revoke_test_order_assignments before update on public.orders
  for each row execute function public.revoke_test_order_assignments();

create function public.driver_orders(target_date date default null, target_assignment uuid default null)
returns table (
  assignment_id uuid, order_id uuid, service_date date, departure_time text,
  pickup text, destination text, vehicle text, status text, version bigint
) language sql stable security definer set search_path = ''
as $$
  select a.id,a.order_id,a.service_date,o.time,o.pickup,o.destination,o.vehicle,a.status,a.version
  from public.driver_identity() identity
  join public.driver_assignments a on a.driver_id=identity.driver_id and a.region_id=identity.region_id
  join public.orders o on o.id=a.order_id and o.region_id=a.region_id
  where a.status <> 'revoked' and o.status <> 'キャンセル'
    and a.service_date between o.date and o.end_date
    and not (a.service_date = any(o.off_dates))
    and ((target_assignment is null and a.service_date=target_date)
         or (target_assignment is not null and a.id=target_assignment))
  order by a.service_date,o.time,a.id limit 200;
$$;

create function public.acknowledge_driver_assignment(
  target_assignment uuid, expected_version bigint, target_request uuid
) returns bigint language plpgsql security definer set search_path = ''
as $$
declare
  link public.driver_auth_links%rowtype;
  item public.driver_assignments%rowtype;
  previous public.driver_assignment_events%rowtype;
  eligible boolean;
begin
  if target_request is null or expected_version is null or expected_version < 1 then
    raise exception 'Request id and version required' using errcode = '22023';
  end if;
  -- Match dispatch/order invalidation lock ordering: order, link, assignment.
  perform 1 from public.orders o join public.driver_assignments a on a.order_id=o.id
    where a.id=target_assignment for share of o;
  select * into link from public.driver_auth_links
    where user_id=(select auth.uid()) and status='active' for share;
  if not found or not exists(select 1 from public.driver_identity()) then
    raise exception 'Active driver identity required' using errcode = '42501';
  end if;
  select * into item from public.driver_assignments
    where id=target_assignment and driver_id=link.driver_id and region_id=link.region_id for update;
  if not found or item.status='revoked' then
    raise exception 'Assignment not available' using errcode = 'P0002';
  end if;
  select exists(select 1 from public.driver_orders(null,target_assignment)) into eligible;
  if not eligible then raise exception 'Assignment not available' using errcode = 'P0002'; end if;
  select * into previous from public.driver_assignment_events
    where actor_user_id=(select auth.uid()) and request_id=target_request;
  if found then
    if previous.assignment_id <> target_assignment or item.version <> expected_version+1 then
      raise exception 'Idempotency key payload conflict' using errcode = '40001';
    end if;
    return item.version;
  end if;
  if item.version <> expected_version or item.status <> 'assigned' then
    raise exception 'Assignment version/state conflict' using errcode = '40001';
  end if;
  insert into public.driver_assignment_events(assignment_id,actor_user_id,event_type,request_id)
    values(item.id,(select auth.uid()),'acknowledged',target_request);
  update public.driver_assignments set status='acknowledged',version=version+1,acknowledged_at=now()
    where id=item.id returning version into item.version;
  return item.version;
end;
$$;

revoke all on function public.revoke_test_order_assignments() from public,anon,authenticated;
revoke all on function public.dispatch_test_driver_order(uuid,uuid,date),
  public.driver_orders(date,uuid),public.acknowledge_driver_assignment(uuid,bigint,uuid)
  from public,anon;
grant execute on function public.dispatch_test_driver_order(uuid,uuid,date),
  public.driver_orders(date,uuid),public.acknowledge_driver_assignment(uuid,bigint,uuid)
  to authenticated;
select 'driver_trips_prepared' as result;


-- Source: 005-driver-execution.sql; SHA256: 9c1a3688927ea6b60010473ddd12386959392bd8820e701dd5f466b066dff679
set local lock_timeout = '3s';
set local statement_timeout = '20s';

alter table public.driver_assignments drop constraint driver_assignments_status_check;
alter table public.driver_assignments add constraint driver_assignments_status_check
  check (status in ('assigned','acknowledged','en_route','arrived','in_service','completed','revoked'));
alter table public.driver_assignment_events drop constraint driver_assignment_events_event_type_check;
alter table public.driver_assignment_events add constraint driver_assignment_events_event_type_check
  check (event_type in ('acknowledged','en_route','arrived','in_service','completed','revoked'));
alter table public.driver_assignment_events
  add column expected_version bigint,
  add column result_version bigint;
-- Before this expansion, every acknowledgement was the single assigned v1 -> acknowledged v2.
update public.driver_assignment_events set expected_version=1,result_version=2
  where event_type='acknowledged';
alter table public.driver_assignment_events add constraint driver_event_versions_check check (
  (event_type='revoked' and expected_version is null and result_version is null)
  or (event_type<>'revoked' and expected_version is not null and expected_version>0
      and result_version is not null and result_version=expected_version+1 and request_id is not null)
);

create function public.transition_driver_assignment(
  target_assignment uuid, expected_version bigint, target_request uuid, target_state text
) returns bigint language plpgsql security definer set search_path = ''
as $$
declare
  link public.driver_auth_links%rowtype;
  item public.driver_assignments%rowtype;
  previous public.driver_assignment_events%rowtype;
  next_state text;
begin
  if target_request is null or expected_version is null or expected_version < 1
     or expected_version >= 9007199254740991 or target_state is null
     or target_state not in ('acknowledged','en_route','arrived','in_service','completed') then
    raise exception 'Valid request, version and state required' using errcode='22023';
  end if;
  -- Match dispatch and order-edit lock ordering.
  perform 1 from public.orders o join public.driver_assignments a on a.order_id=o.id
    where a.id=target_assignment for share of o;
  select * into link from public.driver_auth_links
    where user_id=(select auth.uid()) and status='active' for share;
  if not found or not exists(select 1 from public.driver_identity()) then
    raise exception 'Active driver identity required' using errcode='42501';
  end if;
  select * into item from public.driver_assignments
    where id=target_assignment and driver_id=link.driver_id and region_id=link.region_id for update;
  if not found or item.status='revoked'
     or not exists(select 1 from public.driver_orders(null,target_assignment)) then
    raise exception 'Assignment not available' using errcode='P0002';
  end if;
  select * into previous from public.driver_assignment_events
    where actor_user_id=(select auth.uid()) and request_id=target_request;
  if found then
    if previous.assignment_id<>target_assignment or previous.event_type<>target_state
       or previous.expected_version is distinct from expected_version then
      raise exception 'Idempotency key payload conflict' using errcode='40001';
    end if;
    return previous.result_version;
  end if;
  next_state:=case item.status when 'assigned' then 'acknowledged'
    when 'acknowledged' then 'en_route' when 'en_route' then 'arrived'
    when 'arrived' then 'in_service' when 'in_service' then 'completed' else null end;
  if item.version<>expected_version or next_state is distinct from target_state then
    raise exception 'Assignment version/state conflict' using errcode='40001';
  end if;
  insert into public.driver_assignment_events(
    assignment_id,actor_user_id,event_type,request_id,expected_version,result_version)
    values(item.id,(select auth.uid()),target_state,target_request,expected_version,expected_version+1);
  update public.driver_assignments set status=target_state,version=version+1,
    acknowledged_at=case when target_state='acknowledged' then now() else acknowledged_at end
    where id=item.id returning version into item.version;
  return item.version;
end;
$$;

create or replace function public.acknowledge_driver_assignment(
  target_assignment uuid, expected_version bigint, target_request uuid
) returns bigint language sql security definer set search_path = ''
as $$
  select public.transition_driver_assignment(target_assignment,expected_version,target_request,'acknowledged');
$$;
revoke all on function public.transition_driver_assignment(uuid,bigint,uuid,text) from public,anon;
grant execute on function public.transition_driver_assignment(uuid,bigint,uuid,text) to authenticated;


-- Source: 006-driver-reports.sql; SHA256: 8fbd703d2d0b4ea4a6ec7ee2a27c53879e2fc1db71c4cf5355b63ec57f9803c3
set local lock_timeout='3s';
set local statement_timeout='20s';
create table public.driver_report_depots (
  driver_id uuid primary key,
  region_id uuid not null,
  name text not null check(length(name) between 1 and 100),
  address text not null check(length(address) between 1 and 300),
  updated_at timestamptz not null default now(),
  updated_by uuid not null references auth.users(id),
  foreign key(driver_id,region_id) references public.drivers(id,region_id) on delete restrict
);
create table public.driver_daily_reports (
  id uuid primary key default gen_random_uuid(),
  driver_id uuid not null, region_id uuid not null,
  service_date date not null,
  departed_at timestamptz not null, departure_address text not null, departure_km numeric not null,
  returned_at timestamptz, return_address text, return_km numeric,
  stops jsonb not null default '[]', rests jsonb not null default '[]',
  version bigint not null default 1,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  created_by uuid not null references auth.users(id), updated_by uuid not null references auth.users(id),
  foreign key(driver_id,region_id) references public.drivers(id,region_id) on delete restrict,
  check(version>0 and departure_km>=0 and departure_km<=9999999),
  check(jsonb_typeof(stops)='array' and jsonb_typeof(rests)='array'),
  check((returned_at is null and return_address is null and return_km is null)
    or (returned_at>=departed_at and length(return_address) between 1 and 300 and return_km>=departure_km))
);
create unique index driver_report_one_open on public.driver_daily_reports(driver_id) where returned_at is null;
create index driver_report_history on public.driver_daily_reports(driver_id,departed_at desc);
create table public.driver_report_events (
  id uuid primary key default gen_random_uuid(),
  report_id uuid not null references public.driver_daily_reports(id) on delete restrict,
  actor_user_id uuid not null references auth.users(id),
  request_id uuid not null, command jsonb not null,
  before_data jsonb, after_data jsonb not null,
  occurred_at timestamptz not null default now(),
  unique(actor_user_id,request_id)
);
alter table public.driver_report_depots enable row level security;
alter table public.driver_daily_reports enable row level security;
alter table public.driver_report_events enable row level security;
revoke all on public.driver_report_depots,public.driver_daily_reports,public.driver_report_events from public,anon,authenticated;

create function public.driver_report_projection(r public.driver_daily_reports) returns jsonb
language sql stable set search_path='' as $$
 select jsonb_build_object('id',r.id,'serviceDate',r.service_date,'version',r.version,
 'departedAt',r.departed_at,'departureAddress',r.departure_address,'departureKm',r.departure_km,
 'returnedAt',r.returned_at,'returnAddress',r.return_address,'returnKm',r.return_km,'stops',r.stops,'rests',r.rests);
$$;
create function public.driver_reports() returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('reports',coalesce((select jsonb_agg(public.driver_report_projection(r) order by r.departed_at desc)
 from (select d.* from public.driver_daily_reports d join public.driver_identity() i
 on d.driver_id=i.driver_id and d.region_id=i.region_id order by d.departed_at desc limit 31) r),'[]'::jsonb),
 'depot',(select jsonb_build_object('name',d.name,'address',d.address) from public.driver_report_depots d
 join public.driver_identity() i on d.driver_id=i.driver_id and d.region_id=i.region_id));
$$;

create function public.validate_driver_report(r public.driver_daily_reports) returns void
language plpgsql set search_path='' as $$
declare s jsonb; t timestamptz:=r.departed_at; k numeric:=r.departure_km;
 a timestamptz; b timestamptz; n numeric; pending boolean:=false; stop_ids text[]:='{}';
 finish timestamptz:=coalesce(r.returned_at,clock_timestamp());
begin
 if jsonb_array_length(r.stops)>100 or jsonb_array_length(r.rests)>100 then
  raise exception 'Maximum 100 stops and rest periods' using errcode='22023'; end if;
 for s in select value from jsonb_array_elements(r.stops) loop
  if pending or length(btrim(s->>'address')) not between 1 and 300 or s->>'id'=any(stop_ids) then
   raise exception 'Finish previous stop or check address' using errcode='22023'; end if;
  stop_ids:=array_append(stop_ids,s->>'id');
  a:=(s->>'arrivedAt')::timestamptz; b:=(s->>'departedAt')::timestamptz;
  n:=(s->>'arrivedKm')::numeric;
  if (a is null)<>(n is null) or (a is null and b is not null) then
   raise exception 'Arrival time and odometer required together' using errcode='22023'; end if;
  if a is not null then
   if a<t or a>finish or n<k or n>9999999 or n<>round(n,1) then
    raise exception 'Arrival time or odometer out of order' using errcode='22023'; end if;
   t:=a; k:=n;
  end if;
  n:=(s->>'departedKm')::numeric;
  if (b is null)<>(n is null) then raise exception 'Departure time and odometer required together' using errcode='22023'; end if;
  if b is not null then
   if b<t or b>finish or n<k or n>9999999 or n<>round(n,1) then
    raise exception 'Departure time or odometer out of order' using errcode='22023'; end if;
   t:=b; k:=n;
  else pending:=true; end if;
 end loop;
 if r.returned_at is not null and (pending or r.returned_at<t or r.return_km<k) then
  raise exception 'Finish stops and check return odometer' using errcode='22023'; end if;
 t:=r.departed_at; pending:=false;
 for s in select value from jsonb_array_elements(r.rests) loop
  a:=(s->>'startedAt')::timestamptz; b:=(s->>'endedAt')::timestamptz;
  if pending or a is null or a<t or a>finish or (b is not null and (b<a or b>finish)) then
   raise exception 'Rest periods overlap or exceed shift' using errcode='22023'; end if;
  if b is null then pending:=true; else t:=b; end if;
 end loop;
 if pending and r.returned_at is not null then raise exception 'End rest before return' using errcode='22023'; end if;
end;
$$;

create function public.driver_report_command(
 target_report uuid, expected_version bigint, target_request uuid, target_action text, payload jsonb
) returns jsonb language plpgsql security definer set search_path='' as $$
declare
 link public.driver_auth_links%rowtype; r public.driver_daily_reports%rowtype;
 previous public.driver_report_events%rowtype; old_data jsonb; result jsonb;
 cmd jsonb; address text; km numeric; stamp timestamptz:=clock_timestamp();
 idx integer; s jsonb; allowed text[];
begin
 select * into link from public.driver_auth_links where user_id=(select auth.uid()) and status='active' for update;
 if not found or not exists(select 1 from public.driver_identity()) then
  raise exception 'Active driver required' using errcode='42501'; end if;
 if target_request is null or expected_version is null or expected_version<0 or expected_version>=9007199254740991
 or target_action is null or jsonb_typeof(payload) is distinct from 'object' then
  raise exception 'Invalid report command' using errcode='22023'; end if;
 allowed:=case target_action when 'checkout' then array['useDefault','address','km'] when 'return' then array['useDefault','address','km']
 when 'add_stop' then array['address'] when 'arrive' then array['stopId','km'] when 'depart' then array['stopId','km']
 when 'edit_stop' then array['id','address','arrivedAt','arrivedKm','departedAt','departedKm','reason']
 when 'rest_start' then array[]::text[] when 'rest_end' then array[]::text[] else null end;
 if allowed is null or not (payload ?& allowed) or exists(select 1 from jsonb_object_keys(payload) k where not(k=any(allowed))) then
  raise exception 'Unexpected or missing report fields' using errcode='22023'; end if;
 cmd:=jsonb_build_object('reportId',target_report,'version',expected_version,'action',target_action,'payload',payload);
 select * into previous from public.driver_report_events where actor_user_id=(select auth.uid()) and request_id=target_request;
 if found then
  if previous.command<>cmd then raise exception 'Request key conflict' using errcode='40001'; end if;
  return previous.after_data;
 end if;
 if target_action in ('checkout','return','arrive','depart') then
  if jsonb_typeof(payload->'km')<>'number' then raise exception 'Numeric odometer required' using errcode='22023'; end if;
  km:=(payload->>'km')::numeric;
  if km<0 or km>9999999 or km<>round(km,1) then raise exception 'Invalid odometer' using errcode='22023'; end if;
 end if;
 if target_action in ('checkout','return') then
  if jsonb_typeof(payload->'useDefault')<>'boolean' or jsonb_typeof(payload->'address')<>'string' then
   raise exception 'Invalid location' using errcode='22023'; end if;
  if (payload->>'useDefault')::boolean then
   select d.address into address from public.driver_report_depots d where d.driver_id=link.driver_id and d.region_id=link.region_id;
  else address:=btrim(payload->>'address'); end if;
  if address is null or length(address) not between 1 and 300 then raise exception 'Depot not configured or location missing' using errcode='22023'; end if;
 end if;
 if target_action='checkout' then
  if target_report is not null or expected_version<>0 or exists(select 1 from public.driver_daily_reports where driver_id=link.driver_id and returned_at is null) then
   raise exception 'Open report already exists or invalid version' using errcode='40001'; end if;
  insert into public.driver_daily_reports(driver_id,region_id,service_date,departed_at,departure_address,departure_km,created_by,updated_by)
   values(link.driver_id,link.region_id,(stamp at time zone 'Asia/Tokyo')::date,stamp,address,km,(select auth.uid()),(select auth.uid())) returning * into r;
 else
  select * into r from public.driver_daily_reports where id=target_report and driver_id=link.driver_id and region_id=link.region_id for update;
  if not found then raise exception 'Report not available' using errcode='P0002'; end if;
  if r.version<>expected_version or (r.returned_at is not null and target_action<>'edit_stop') then
   raise exception 'Report version or state changed' using errcode='40001'; end if;
  old_data:=public.driver_report_projection(r);
  if target_action='return' then r.returned_at:=stamp; r.return_address:=address; r.return_km:=km;
  elsif target_action='add_stop' then
   if jsonb_typeof(payload->'address')<>'string' or length(btrim(payload->>'address')) not between 1 and 300 then
    raise exception 'Stop address required' using errcode='22023'; end if;
   r.stops:=r.stops||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'address',btrim(payload->>'address'),
    'arrivedAt',null,'arrivedKm',null,'departedAt',null,'departedKm',null));
  elsif target_action in ('arrive','depart','edit_stop') then
   select ordinality::integer-1,value into idx,s from jsonb_array_elements(r.stops) with ordinality
    where value->>'id'=case when target_action='edit_stop' then payload->>'id' else payload->>'stopId' end;
   if idx is null then raise exception 'Stop not found' using errcode='P0002'; end if;
   if target_action='edit_stop' then
    if jsonb_typeof(payload->'address')<>'string' or jsonb_typeof(payload->'reason')<>'string'
      or length(btrim(payload->>'reason')) not between 1 and 300
      or jsonb_typeof(payload->'arrivedAt') not in ('null','string') or jsonb_typeof(payload->'departedAt') not in ('null','string')
      or jsonb_typeof(payload->'arrivedKm') not in ('null','number') or jsonb_typeof(payload->'departedKm') not in ('null','number')
    then raise exception 'Correction needs valid fields and reason' using errcode='22023'; end if;
    s:=payload-'reason';
   elsif target_action='arrive' then
    if s->>'arrivedAt' is not null then raise exception 'Already arrived' using errcode='40001'; end if;
    s:=s||jsonb_build_object('arrivedAt',stamp,'arrivedKm',km);
   else
    if s->>'arrivedAt' is null or s->>'departedAt' is not null then raise exception 'Arrival required before departure' using errcode='40001'; end if;
    s:=s||jsonb_build_object('departedAt',stamp,'departedKm',km);
   end if;
   r.stops:=jsonb_set(r.stops,array[idx::text],s);
  elsif target_action='rest_start' then
   r.rests:=r.rests||jsonb_build_array(jsonb_build_object('startedAt',stamp,'endedAt',null));
  elsif target_action='rest_end' then
   idx:=jsonb_array_length(r.rests)-1;
   if idx<0 or r.rests->idx->>'endedAt' is not null then raise exception 'No active rest' using errcode='40001'; end if;
   r.rests:=jsonb_set(r.rests,array[idx::text,'endedAt'],to_jsonb(stamp));
  end if;
  perform public.validate_driver_report(r);
  update public.driver_daily_reports set returned_at=r.returned_at,return_address=r.return_address,return_km=r.return_km,
   stops=r.stops,rests=r.rests,version=version+1,updated_at=stamp,updated_by=(select auth.uid())
   where id=r.id returning * into r;
 end if;
 result:=public.driver_report_projection(r);
 insert into public.driver_report_events(report_id,actor_user_id,request_id,command,before_data,after_data)
  values(r.id,(select auth.uid()),target_request,cmd,old_data,result);
 return result;
end;
$$;
revoke all on function public.driver_report_projection(public.driver_daily_reports),
 public.validate_driver_report(public.driver_daily_reports) from public,anon,authenticated;
revoke all on function public.driver_reports(),public.driver_report_command(uuid,bigint,uuid,text,jsonb) from public,anon;
grant execute on function public.driver_reports(),public.driver_report_command(uuid,bigint,uuid,text,jsonb) to authenticated;


