create table public.driver_finance_claims (
 assignment_id uuid primary key references public.driver_assignments(id),
 driver_id uuid not null references public.drivers(id),
 region_id uuid not null references public.regions(id),
 version bigint not null default 1,
 status text not null check(status in ('pending','approved','rejected')),
 expenses jsonb not null, overtime_hours numeric not null,
 baseline jsonb not null, request_id uuid not null,
 submitted_at timestamptz not null default now(), reviewed_at timestamptz,
 reviewed_by uuid references auth.users(id), review_note text not null default ''
);
alter table public.driver_finance_claims enable row level security;
revoke all on public.driver_finance_claims from public,anon,authenticated;
create table public.driver_finance_events (
 id uuid primary key default gen_random_uuid(), assignment_id uuid not null references public.driver_assignments(id),
 actor_id uuid references auth.users(id), occurred_at timestamptz not null default now(), snapshot jsonb not null
);
alter table public.driver_finance_events enable row level security;
revoke all on public.driver_finance_events from public,anon,authenticated;
create function public.record_driver_finance_event() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 insert into public.driver_finance_events(assignment_id,actor_id,snapshot)
 values(new.assignment_id,auth.uid(),to_jsonb(new));
 return new;
end;
$$;
create trigger driver_finance_event after insert or update on public.driver_finance_claims
 for each row execute function public.record_driver_finance_event();
create function public.driver_finance_claim_json(c public.driver_finance_claims)
returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_object('assignmentId',c.assignment_id,'version',c.version,'status',c.status,
 'expenses',c.expenses,'overtimeHours',c.overtime_hours,'reviewNote',c.review_note,'submittedAt',c.submitted_at);
$$;
create function public.driver_finance_baseline(f jsonb) returns jsonb
language sql immutable set search_path='' as $$
 select jsonb_build_object('driver',f->'driver','driverPaymentType',f->'driverPaymentType',
 'driverAdvanceCompanyReport',f->'driverAdvanceCompanyReport','driverAdvanceTripReport',f->'driverAdvanceTripReport',
 'driverOvertimeHours',f->'driverOvertimeHours','driverOvertimeRate',f->'driverOvertimeRate',
 'driverOvertimeFee',f->'driverOvertimeFee','overtimeRequestAmount',f->'overtimeRequestAmount',
 'overtimeRequestRate',f->'overtimeRequestRate');
$$;
create function public.driver_finance_data(target_month text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare identity record; trips jsonb; wages jsonb; manual_items jsonb;
begin
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 if target_month is null or target_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then
  raise exception 'Invalid month' using errcode='22023'; end if;
 if (select count(*) from public.drivers where region_id=identity.region_id and name=identity.driver_name)<>1 then
  raise exception 'Ambiguous payroll driver name; contact admin' using errcode='42501'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('assignmentId',a.id,'date',a.service_date,
  'pickup',o.pickup,'destination',o.destination,
  'existingOvertimeHours',coalesce((o.finance_by_date->a.service_date::text->>'driverOvertimeHours')::numeric,0),
  'claim',case when c.assignment_id is null then null else public.driver_finance_claim_json(c) end)
  order by a.service_date,o.time,a.id),'[]') into trips
 from public.driver_assignments a join public.orders o on o.id=a.order_id and o.region_id=a.region_id
 left join public.driver_finance_claims c on c.assignment_id=a.id and c.driver_id=identity.driver_id
 where a.driver_id=identity.driver_id and a.region_id=identity.region_id and a.status='completed'
 and to_char(a.service_date,'YYYY-MM')=target_month and a.service_date <= (now() at time zone 'Asia/Tokyo')::date
 and o.status<>'キャンセル' and a.service_date between o.date and o.end_date and not(a.service_date=any(o.off_dates));
 -- Existing staff payroll keys by region + driver name; fail closed on duplicate names above.
 select coalesce(jsonb_agg(jsonb_build_object('date',a.service_date,
 'base',case when f->>'driverWageMode'='percentage' then greatest(0,round((
   coalesce((f->>'dailyFare')::numeric,0)+coalesce((f->>'etcTripReport')::numeric,0)+
   coalesce((f->>'driverAdvanceTripReport')::numeric,0)+coalesce((f->>'companyAdvanceTripReport')::numeric,0)+
   case when f ? 'overtimeRequestRate' then
    round(coalesce((f->>'driverOvertimeHours')::numeric,0)*coalesce((f->>'overtimeRequestRate')::numeric,0))
   else coalesce((f->>'overtimeRequestAmount')::numeric,
    case when coalesce((f->>'driverOvertimeRate')::numeric,0)>0 then
     round(coalesce((f->>'driverOvertimeHours')::numeric,0)*(f->>'driverOvertimeRate')::numeric)
    else coalesce((f->>'driverOvertimeFee')::numeric,0) end) end-
   coalesce((f->>'etcCompanyReport')::numeric,0)-coalesce((f->>'fuelCost')::numeric,0)-
   coalesce((f->>'companyAdvanceCompanyReport')::numeric,0)-coalesce((f->>'driverAdvanceCompanyReport')::numeric,0)-
   coalesce((f->>'driverAdvanceTripReport')::numeric,0))*coalesce((f->>'driverWagePercentage')::numeric,50)/100))
   else coalesce((f->>'driverWage')::numeric,0) end,
 'bonus',coalesce((f->>'driverBonusWage')::numeric,0),
 'overtime',case when coalesce((f->>'driverOvertimeRate')::numeric,0)>0
  then round(coalesce((f->>'driverOvertimeHours')::numeric,0)*(f->>'driverOvertimeRate')::numeric)
  else coalesce((f->>'driverOvertimeFee')::numeric,0) end,
 'advances',coalesce((f->>'driverAdvanceCompanyReport')::numeric,0)+coalesce((f->>'driverAdvanceTripReport')::numeric,0))
 order by a.service_date,a.id),'[]') into wages
 from public.orders o cross join lateral jsonb_each(coalesce(o.finance_by_date,'{}')) entry
 cross join lateral (select entry.key::date as service_date,o.id,entry.value as f) a
 where o.region_id=identity.region_id and to_char(a.service_date,'YYYY-MM')=target_month
 and f->>'driver'=identity.driver_name and coalesce(f->>'driverPaymentType','')<>'company_advance';
 select coalesce(jsonb_agg(jsonb_build_object('name',name,'amount',amount) order by name,id),'[]')
 into manual_items from public.driver_wage_items
 where region_id=identity.region_id and driver=identity.driver_name and month=target_month;
 return jsonb_build_object('trips',trips,'wages',wages,'manualItems',manual_items);
end;
$$;
create function public.submit_driver_finance(target_assignment uuid, expected_version bigint,
 target_request uuid, items jsonb, hours numeric) returns jsonb
language plpgsql security definer set search_path='' as $$
declare identity record; a public.driver_assignments; o public.orders; c public.driver_finance_claims;
 e jsonb; p text; total numeric:=0; f jsonb;
begin
 -- Same order/link/assignment locking order as dispatch and report workflows.
 select ord.* into o from public.orders ord join public.driver_assignments x on x.order_id=ord.id
 where x.id=target_assignment for share of ord;
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 perform 1 from public.driver_auth_links where driver_id=identity.driver_id for share;
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 select * into a from public.driver_assignments where id=target_assignment
  and driver_id=identity.driver_id and region_id=identity.region_id for update;
 if not found or a.status<>'completed' or o.status='キャンセル'
 or a.service_date>(now() at time zone 'Asia/Tokyo')::date or a.service_date<o.date
 or a.service_date>o.end_date or a.service_date=any(o.off_dates) then
  raise exception 'Completed own trip required' using errcode='42501'; end if;
 if target_request is null or expected_version is null or expected_version<0
 or hours is null or hours<0 or hours>999 or hours<>round(hours,2)
 or jsonb_typeof(items) is distinct from 'array' or jsonb_array_length(items)>50 then
  raise exception 'Invalid submission' using errcode='22023'; end if;
 for e in select value from jsonb_array_elements(items) loop
  if jsonb_typeof(e) is distinct from 'object' or not(e ?& array['id','type','detail','amount','receipts'])
  or exists(select 1 from jsonb_object_keys(e) k where k<>all(array['id','type','detail','amount','receipts']))
  or e->>'type' not in ('company','trip') or jsonb_typeof(e->'type') is distinct from 'string'
  or jsonb_typeof(e->'detail') is distinct from 'string' or length(btrim(e->>'detail')) not between 1 and 200
  or jsonb_typeof(e->'amount') is distinct from 'number'
  or jsonb_typeof(e->'receipts') is distinct from 'array' or jsonb_array_length(e->'receipts')>5
  or jsonb_typeof(e->'id') is distinct from 'string' then
   raise exception 'Invalid expense' using errcode='22023'; end if;
  perform (e->>'id')::uuid;
  if (e->>'amount')::numeric<=0 or (e->>'amount')::numeric<>trunc((e->>'amount')::numeric) then
   raise exception 'Invalid expense amount' using errcode='22023'; end if;
  total:=total+(e->>'amount')::numeric;
  for p in select jsonb_array_elements_text(e->'receipts') loop
   if p !~ ('^'||auth.uid()::text||'/'||a.id::text||'/[0-9a-f-]{36}\.(jpg|png|webp)$')
   or not exists(select 1 from storage.objects where bucket_id='driver-finance-receipts' and name=p) then
    raise exception 'Receipt not available' using errcode='42501'; end if;
  end loop;
 end loop;
 if total>99999999999999 or
 (select count(distinct value->>'id') from jsonb_array_elements(items))<>jsonb_array_length(items) then
  raise exception 'Invalid expense totals' using errcode='22023'; end if;
 select * into c from public.driver_finance_claims where assignment_id=a.id for update;
 if found and c.request_id=target_request then
  if c.expenses<>items or c.overtime_hours<>hours then
   raise exception 'Request key payload changed' using errcode='40001'; end if;
  return public.driver_finance_claim_json(c);
 end if;
 if (c.assignment_id is null and expected_version<>0) or
 (c.assignment_id is not null and (c.version<>expected_version or c.status<>'rejected')) then
  raise exception 'Claim already submitted or changed' using errcode='40001'; end if;
 f:=coalesce(o.finance_by_date->a.service_date::text,'{}');
 insert into public.driver_finance_claims(assignment_id,driver_id,region_id,status,expenses,overtime_hours,baseline,request_id)
 values(a.id,a.driver_id,a.region_id,'pending',items,hours,public.driver_finance_baseline(f),target_request)
 on conflict(assignment_id) do update set version=driver_finance_claims.version+1,status='pending',
 expenses=excluded.expenses,overtime_hours=excluded.overtime_hours,baseline=excluded.baseline,request_id=excluded.request_id,
 submitted_at=now(),review_note='',reviewed_at=null,reviewed_by=null returning * into c;
 return public.driver_finance_claim_json(c);
end;
$$;
create function public.review_driver_finance(target_assignment uuid, expected_version bigint, decision text, note text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare c public.driver_finance_claims; a public.driver_assignments; o public.orders;
 f jsonb; company_sum numeric; trip_sum numeric; driver_name text; rate numeric;
begin
 if not public.is_admin() then raise exception 'Staff admin required' using errcode='42501'; end if;
 select ord.* into o from public.orders ord join public.driver_assignments x on x.order_id=ord.id
 where x.id=target_assignment for update of ord;
 select * into a from public.driver_assignments where id=target_assignment for update;
 select * into c from public.driver_finance_claims where assignment_id=target_assignment for update;
 if not found or c.version is distinct from expected_version or c.status<>'pending' then
  raise exception 'Pending claim changed' using errcode='40001'; end if;
 if decision is null or decision not in ('approved','rejected') or note is null or length(note)>500
 or (decision='rejected' and length(btrim(note))=0) then
  raise exception 'Invalid review' using errcode='22023'; end if;
 if decision='approved' then
  if a.status<>'completed' or o.status='キャンセル' or a.service_date<o.date or a.service_date>o.end_date
  or a.service_date=any(o.off_dates) then raise exception 'Trip changed' using errcode='40001'; end if;
  f:=coalesce(o.finance_by_date->a.service_date::text,'{}');
  select name into driver_name from public.drivers where id=c.driver_id and region_id=c.region_id;
  if public.driver_finance_baseline(f)<>c.baseline or coalesce(f->>'driver',o.driver)<>driver_name
  or coalesce(f->>'driverPaymentType','')='company_advance' then
   raise exception 'Finance/driver changed; reject for resubmission' using errcode='40001'; end if;
  select coalesce(sum((value->>'amount')::numeric) filter(where value->>'type'='company'),0),
   coalesce(sum((value->>'amount')::numeric) filter(where value->>'type'='trip'),0)
  into company_sum,trip_sum from jsonb_array_elements(c.expenses);
  company_sum:=company_sum+coalesce((f->>'driverAdvanceCompanyReport')::numeric,0);
  trip_sum:=trip_sum+coalesce((f->>'driverAdvanceTripReport')::numeric,0);
  rate:=coalesce((f->>'driverOvertimeRate')::numeric,0);
  if greatest(company_sum,trip_sum,round(rate*c.overtime_hours),
   round(coalesce((f->>'overtimeRequestRate')::numeric,0)*c.overtime_hours))>99999999999999 then
   raise exception 'Finance limit exceeded' using errcode='22023'; end if;
  f:=f||jsonb_build_object('driver',driver_name,'driverAdvanceCompanyReport',company_sum,
   'driverAdvanceTripReport',trip_sum,'driverOvertimeHours',c.overtime_hours,
   'driverOvertimeFee',case when rate>0 then round(rate*c.overtime_hours) else coalesce((f->>'driverOvertimeFee')::numeric,0) end);
  if f ? 'overtimeRequestRate' then
   f:=f||jsonb_build_object('overtimeRequestAmount',round(c.overtime_hours*coalesce((f->>'overtimeRequestRate')::numeric,0)));
  end if;
  update public.orders set finance_by_date=jsonb_set(coalesce(finance_by_date,'{}'),array[a.service_date::text],f,true) where id=o.id;
 end if;
 update public.driver_finance_claims set status=decision,version=version+1,review_note=btrim(note),
 reviewed_at=now(),reviewed_by=auth.uid() where assignment_id=c.assignment_id returning * into c;
 return public.driver_finance_claim_json(c);
end;
$$;
create function public.admin_driver_finance(target_month text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.is_admin() then raise exception 'Admin required' using errcode='42501'; end if;
 if target_month is null or target_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then
  raise exception 'Invalid month' using errcode='22023'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('driverName',d.name,'date',a.service_date,
  'pickup',o.pickup,'destination',o.destination,'claim',public.driver_finance_claim_json(c)) order by c.submitted_at)
  from public.driver_finance_claims c join public.driver_assignments a on a.id=c.assignment_id
  join public.orders o on o.id=a.order_id join public.drivers d on d.id=c.driver_id
  where to_char(a.service_date,'YYYY-MM')=target_month),'[]');
end;
$$;
-- Finance-only approval must not revoke the executed assignment. Dispatch changes still revoke.
do $patch$
declare d text;
begin
 d:=pg_get_functiondef('public.revoke_test_order_assignments()'::regprocedure);
 if position('for changed in' in d)=0 then raise exception 'Unknown revocation function'; end if;
 d:=replace(d,'for changed in',
  'if (to_jsonb(new)-''finance_by_date''-''last_operation'') = (to_jsonb(old)-''finance_by_date''-''last_operation'')
   and not exists(select 1 from (select jsonb_object_keys(coalesce(new.finance_by_date,''{}'')) as day
    union select jsonb_object_keys(coalesce(old.finance_by_date,''{}''))) dates
    where coalesce(new.finance_by_date->day->>''driver'',new.driver) is distinct from coalesce(old.finance_by_date->day->>''driver'',old.driver)
     or coalesce(new.finance_by_date->day->>''vehicle'',new.vehicle) is distinct from coalesce(old.finance_by_date->day->>''vehicle'',old.vehicle)
     or coalesce(new.finance_by_date->day->>''vehiclePlate'',to_jsonb(new)->>''vehicle_plate'') is distinct from coalesce(old.finance_by_date->day->>''vehiclePlate'',to_jsonb(old)->>''vehicle_plate'')
     or new.finance_by_date->day->>''driverPaymentType'' is distinct from old.finance_by_date->day->>''driverPaymentType'')
   then return new; end if;
  for changed in');
 execute d;
end;
$patch$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('driver-finance-receipts','driver-finance-receipts',false,5242880,array['image/jpeg','image/png','image/webp']);
create function public.can_access_driver_receipt(path text, writing boolean) returns boolean
language plpgsql stable security definer set search_path='' as $$
begin
 if path !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png|webp)$' then return false; end if;
 if not writing and public.is_admin() then return true; end if;
 return exists(select 1 from public.driver_identity() identity join public.driver_assignments a
  on a.driver_id=identity.driver_id and a.region_id=identity.region_id
  where split_part(path,'/',1)=auth.uid()::text and a.id::text=split_part(path,'/',2) and a.status='completed'
  and (not writing or not exists(select 1 from public.driver_finance_claims c where c.assignment_id=a.id and c.status<>'rejected')));
end;
$$;
create policy driver_receipt_insert on storage.objects for insert to authenticated
 with check(bucket_id='driver-finance-receipts' and public.can_access_driver_receipt(name,true));
create policy driver_receipt_select on storage.objects for select to authenticated
 using(bucket_id='driver-finance-receipts' and public.can_access_driver_receipt(name,false));
revoke all on function public.record_driver_finance_event(),
 public.driver_finance_claim_json(public.driver_finance_claims),public.driver_finance_baseline(jsonb)
 from public,anon,authenticated;
revoke all on function public.driver_finance_data(text),public.submit_driver_finance(uuid,bigint,uuid,jsonb,numeric),
 public.review_driver_finance(uuid,bigint,text,text),public.admin_driver_finance(text),public.can_access_driver_receipt(text,boolean) from public,anon;
grant execute on function public.driver_finance_data(text),public.submit_driver_finance(uuid,bigint,uuid,jsonb,numeric),
 public.review_driver_finance(uuid,bigint,text,text),public.admin_driver_finance(text),public.can_access_driver_receipt(text,boolean) to authenticated;


-- Source: 020-finance-categories.sql; SHA256: 436fe13806d51392fbb1c3e6a77433c239be0e34c47f312b384b30b18e7f40f2
set local lock_timeout='3s';
set local statement_timeout='30s';
lock table public.driver_finance_claims in access exclusive mode;
create temporary table previous_finance_claims on commit drop as select * from public.driver_finance_claims;
alter table public.driver_finance_claims add column category text not null default 'company'
 check(category in ('company','trip','overtime'));
alter table public.driver_finance_claims drop constraint driver_finance_claims_pkey;
alter table public.driver_finance_claims add primary key(assignment_id,category);
-- Preserve reviewed amounts and versions; splitting an approved record never books it again.
alter table public.driver_finance_claims disable trigger driver_finance_event;
delete from public.driver_finance_claims;
insert into public.driver_finance_claims
 (assignment_id,driver_id,region_id,category,version,status,expenses,overtime_hours,
 baseline,request_id,submitted_at,reviewed_at,reviewed_by,review_note)
select c.assignment_id,c.driver_id,c.region_id,k.category,c.version,c.status,
 coalesce((select jsonb_agg(e) from jsonb_array_elements(c.expenses) e where e->>'type'=k.category),'[]'),
 case when k.category='overtime' then c.overtime_hours else 0 end,
 c.baseline,c.request_id,c.submitted_at,c.reviewed_at,c.reviewed_by,c.review_note
from previous_finance_claims c cross join (values('company'),('trip'),('overtime')) k(category)
where k.category='overtime' or exists(select 1 from jsonb_array_elements(c.expenses) e where e->>'type'=k.category);
alter table public.driver_finance_claims enable trigger driver_finance_event;
alter table public.driver_finance_claims alter column category drop default;

create function public.driver_finance_category_baseline(f jsonb, category text) returns jsonb
language sql immutable set search_path='' as $$
 select jsonb_build_object('driverPaymentType',f->'driverPaymentType') ||
 case category when 'company' then jsonb_build_object('driverAdvanceCompanyReport',f->'driverAdvanceCompanyReport')
 when 'trip' then jsonb_build_object('driverAdvanceTripReport',f->'driverAdvanceTripReport')
 else public.driver_finance_baseline(f)-'driver'-'driverAdvanceCompanyReport'-'driverAdvanceTripReport' end;
$$;
update public.driver_finance_claims set baseline=public.driver_finance_category_baseline(baseline,category);
create or replace function public.driver_finance_claim_json(c public.driver_finance_claims)
returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_object('assignmentId',c.assignment_id,'category',c.category,'version',c.version,'status',c.status,
 'expenses',c.expenses,'overtimeHours',c.overtime_hours,'reviewNote',c.review_note,'submittedAt',c.submitted_at);
$$;
-- Retain the validated payroll formula while changing only the trip's claim projection.
do $patch$
declare d text;
begin
 d:=pg_get_functiondef('public.driver_finance_data(text)'::regprocedure);
 if position('''claim'',case when c.assignment_id is null then null else public.driver_finance_claim_json(c) end' in d)=0 then
  raise exception 'Unexpected finance projection'; end if;
 d:=replace(d,'''claim'',case when c.assignment_id is null then null else public.driver_finance_claim_json(c) end',
  '''claims'',coalesce((select jsonb_agg(public.driver_finance_claim_json(c) order by c.category)
   from public.driver_finance_claims c where c.assignment_id=a.id and c.driver_id=identity.driver_id),''[]''::jsonb)');
 d:=replace(d,'left join public.driver_finance_claims c on c.assignment_id=a.id and c.driver_id=identity.driver_id','');
 execute d;
end;
$patch$;
drop function public.submit_driver_finance(uuid,bigint,uuid,jsonb,numeric);
drop function public.review_driver_finance(uuid,bigint,text,text);
create function public.submit_driver_finance(target_assignment uuid, target_category text, expected_version bigint,
 target_request uuid, items jsonb, hours numeric) returns jsonb
language plpgsql security definer set search_path='' as $$
declare identity record; a public.driver_assignments; o public.orders; c public.driver_finance_claims;
 e jsonb; receipt jsonb; p text; total numeric:=0; f jsonb;
begin
 select ord.* into o from public.orders ord join public.driver_assignments x on x.order_id=ord.id
 where x.id=target_assignment for share of ord;
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 perform 1 from public.driver_auth_links where driver_id=identity.driver_id for share;
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 select * into a from public.driver_assignments where id=target_assignment
  and driver_id=identity.driver_id and region_id=identity.region_id for update;
 if not found or a.status<>'completed' or o.status='キャンセル'
 or a.service_date>(now() at time zone 'Asia/Tokyo')::date or a.service_date<o.date
 or a.service_date>o.end_date or a.service_date=any(o.off_dates) then
  raise exception 'Completed own trip required' using errcode='42501'; end if;
 if target_category is null or target_category not in ('company','trip','overtime')
 or target_request is null or expected_version is null or expected_version<0
 or hours is null or hours::text in ('NaN','Infinity','-Infinity') or hours<0 or hours>999 or hours<>round(hours,2)
 or jsonb_typeof(items) is distinct from 'array' then raise exception 'Invalid submission' using errcode='22023'; end if;
 if jsonb_array_length(items)>50 or
 (target_category='overtime' and items<>'[]') or
 (target_category<>'overtime' and (hours<>0 or jsonb_array_length(items)=0)) then
  raise exception 'Invalid category payload' using errcode='22023'; end if;
 select * into c from public.driver_finance_claims where assignment_id=a.id and category=target_category for update;
 for e in select value from jsonb_array_elements(items) loop
  if jsonb_typeof(e) is distinct from 'object' then raise exception 'Invalid expense' using errcode='22023'; end if;
  if not(e ?& array['id','type','detail','amount','receipts'])
  or exists(select 1 from jsonb_object_keys(e) k where k<>all(array['id','type','detail','amount','receipts']))
  or jsonb_typeof(e->'type') is distinct from 'string' or e->>'type'<>target_category
  or jsonb_typeof(e->'detail') is distinct from 'string' or length(btrim(e->>'detail')) not between 1 and 200
  or jsonb_typeof(e->'amount') is distinct from 'number'
  or jsonb_typeof(e->'receipts') is distinct from 'array' or jsonb_typeof(e->'id') is distinct from 'string' then
   raise exception 'Invalid expense' using errcode='22023'; end if;
  perform (e->>'id')::uuid;
  if (e->>'amount')::numeric<=0 or (e->>'amount')::numeric<>trunc((e->>'amount')::numeric)
  or jsonb_array_length(e->'receipts')>5 then raise exception 'Invalid amount/receipts' using errcode='22023'; end if;
  total:=total+(e->>'amount')::numeric;
  for receipt in select value from jsonb_array_elements(e->'receipts') loop
   if jsonb_typeof(receipt) is distinct from 'string' then raise exception 'Invalid receipt' using errcode='22023'; end if;
   p:=receipt#>>'{}';
   if not exists(select 1 from storage.objects where bucket_id='driver-finance-receipts' and name=p)
   or not (
    p ~ ('^'||auth.uid()::text||'/'||a.id::text||'/'||target_category||'/[0-9a-f-]{36}\.(jpg|png|webp)$')
    or (p ~ ('^'||auth.uid()::text||'/'||a.id::text||'/[0-9a-f-]{36}\.(jpg|png|webp)$')
      and exists(select 1 from jsonb_array_elements(c.expenses) old_expense where old_expense->'receipts' ? p))
   ) then raise exception 'Receipt not available for category' using errcode='42501'; end if;
  end loop;
 end loop;
 if total>99999999999999 or
 (select count(distinct value->>'id') from jsonb_array_elements(items))<>jsonb_array_length(items) then
  raise exception 'Invalid expense totals' using errcode='22023'; end if;
 if c.assignment_id is not null and c.request_id=target_request then
  if c.expenses<>items or c.overtime_hours<>hours then raise exception 'Request key payload changed' using errcode='40001'; end if;
  return public.driver_finance_claim_json(c);
 end if;
 if (c.assignment_id is null and expected_version<>0) or
 (c.assignment_id is not null and (c.version<>expected_version or c.status<>'rejected')) then
  raise exception 'Category already submitted or changed' using errcode='40001'; end if;
 f:=coalesce(o.finance_by_date->a.service_date::text,'{}');
 insert into public.driver_finance_claims
 (assignment_id,category,driver_id,region_id,status,expenses,overtime_hours,baseline,request_id)
 values(a.id,target_category,a.driver_id,a.region_id,'pending',items,hours,public.driver_finance_category_baseline(f,target_category),target_request)
 on conflict(assignment_id,category) do update set version=driver_finance_claims.version+1,status='pending',
 expenses=excluded.expenses,overtime_hours=excluded.overtime_hours,baseline=excluded.baseline,request_id=excluded.request_id,
 submitted_at=now(),review_note='',reviewed_at=null,reviewed_by=null returning * into c;
 return public.driver_finance_claim_json(c);
end;
$$;
create function public.review_driver_finance(target_assignment uuid, target_category text, expected_version bigint,
 decision text, note text) returns jsonb language plpgsql security definer set search_path='' as $$
declare c public.driver_finance_claims; a public.driver_assignments; o public.orders;
 f jsonb; amount numeric; driver_name text; rate numeric; field text;
begin
 if not public.is_admin() then raise exception 'Admin required' using errcode='42501'; end if;
 select ord.* into o from public.orders ord join public.driver_assignments x on x.order_id=ord.id
 where x.id=target_assignment for update of ord;
 select * into a from public.driver_assignments where id=target_assignment for update;
 select * into c from public.driver_finance_claims where assignment_id=target_assignment and category=target_category for update;
 if not found or c.version is distinct from expected_version or c.status<>'pending' then
  raise exception 'Pending category changed' using errcode='40001'; end if;
 if decision is null or decision not in ('approved','rejected') or note is null or length(note)>500
 or (decision='rejected' and length(btrim(note))=0) then raise exception 'Invalid review' using errcode='22023'; end if;
 if decision='approved' then
  if a.status<>'completed' or o.status='キャンセル' or a.service_date<o.date or a.service_date>o.end_date
  or a.service_date=any(o.off_dates) then raise exception 'Trip changed' using errcode='40001'; end if;
  f:=coalesce(o.finance_by_date->a.service_date::text,'{}');
  select name into driver_name from public.drivers where id=c.driver_id and region_id=c.region_id;
  if public.driver_finance_category_baseline(f,target_category)<>c.baseline
  or coalesce(f->>'driver',o.driver) is distinct from driver_name
  or coalesce(f->>'driverPaymentType','')='company_advance' then
   raise exception 'Category finance/driver changed; reject for resubmission' using errcode='40001'; end if;
  if target_category='overtime' then
   rate:=coalesce((f->>'driverOvertimeRate')::numeric,0);
   if greatest(round(rate*c.overtime_hours),round(coalesce((f->>'overtimeRequestRate')::numeric,0)*c.overtime_hours))>99999999999999 then
    raise exception 'Finance limit exceeded' using errcode='22023'; end if;
   f:=f||jsonb_build_object('driverOvertimeHours',c.overtime_hours,
    'driverOvertimeFee',case when rate>0 then round(rate*c.overtime_hours) else coalesce((f->>'driverOvertimeFee')::numeric,0) end);
   if f ? 'overtimeRequestRate' then
    f:=f||jsonb_build_object('overtimeRequestAmount',round(c.overtime_hours*coalesce((f->>'overtimeRequestRate')::numeric,0)));
   end if;
  else
   field:=case when target_category='company' then 'driverAdvanceCompanyReport' else 'driverAdvanceTripReport' end;
   select coalesce(sum((value->>'amount')::numeric),0) into amount from jsonb_array_elements(c.expenses);
   amount:=amount+coalesce((f->>field)::numeric,0);
   if amount>99999999999999 then raise exception 'Finance limit exceeded' using errcode='22023'; end if;
   f:=f||jsonb_build_object(field,amount);
  end if;
  f:=f||jsonb_build_object('driver',driver_name);
  update public.orders set finance_by_date=jsonb_set(coalesce(finance_by_date,'{}'),array[a.service_date::text],f,true) where id=o.id;
 end if;
 update public.driver_finance_claims set status=decision,version=version+1,review_note=btrim(note),
 reviewed_at=now(),reviewed_by=auth.uid() where assignment_id=c.assignment_id and category=c.category returning * into c;
 return public.driver_finance_claim_json(c);
end;
$$;
create or replace function public.can_access_driver_receipt(path text, writing boolean) returns boolean
language plpgsql stable security definer set search_path='' as $$
begin
 if path is null or path !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/((company|trip)/)?[0-9a-f-]{36}\.(jpg|png|webp)$' then return false; end if;
 if not writing and public.is_admin() then return true; end if;
 if writing and split_part(path,'/',3) not in ('company','trip') then return false; end if;
 return exists(select 1 from public.driver_identity() identity join public.driver_assignments a
  on a.driver_id=identity.driver_id and a.region_id=identity.region_id
  join public.orders o on o.id=a.order_id and o.region_id=a.region_id
  where split_part(path,'/',1)=auth.uid()::text and a.id::text=split_part(path,'/',2) and a.status='completed'
  and (not writing or (o.status<>'キャンセル' and a.service_date between o.date and o.end_date
   and not(a.service_date=any(o.off_dates)) and a.service_date<=(now() at time zone 'Asia/Tokyo')::date
   and not exists(select 1 from public.driver_finance_claims c where c.assignment_id=a.id
    and c.category=split_part(path,'/',3) and c.status<>'rejected'))));
end;
$$;
revoke all on function public.driver_finance_category_baseline(jsonb,text) from public,anon,authenticated;
revoke all on function public.submit_driver_finance(uuid,text,bigint,uuid,jsonb,numeric),
 public.review_driver_finance(uuid,text,bigint,text,text) from public,anon;
grant execute on function public.submit_driver_finance(uuid,text,bigint,uuid,jsonb,numeric),
 public.review_driver_finance(uuid,text,bigint,text,text) to authenticated;


-- Source: 021-driver-daily-fuel.sql; SHA256: 08a889cd8f79bd8c5d1f67be993c3184dc8b5ec0ab067b361a79fea9d85eab7a
set local lock_timeout='3s';
set local statement_timeout='30s';
create table public.driver_daily_fuel (
 id uuid primary key default gen_random_uuid(),
 driver_id uuid not null references public.drivers(id),
 region_id uuid not null references public.regions(id),
 assignment_id uuid not null references public.driver_assignments(id), baseline jsonb not null,
 service_date date not null, version bigint not null default 1,
 status text not null check(status in ('pending','approved','rejected')),
 amount bigint not null check(amount between 1 and 99999999999999),
 receipts jsonb not null, request_id uuid not null,
 submitted_at timestamptz not null default now(), reviewed_at timestamptz,
 reviewed_by uuid references auth.users(id), review_note text not null default '',
 unique(driver_id,service_date)
);
alter table public.driver_daily_fuel enable row level security;
revoke all on public.driver_daily_fuel from public,anon,authenticated;
create table public.driver_daily_fuel_events (
 id uuid primary key default gen_random_uuid(), fuel_id uuid not null references public.driver_daily_fuel(id),
 actor_id uuid references auth.users(id), occurred_at timestamptz not null default now(), snapshot jsonb not null
);
alter table public.driver_daily_fuel_events enable row level security;
revoke all on public.driver_daily_fuel_events from public,anon,authenticated;
-- One approved daily cost, linked to exactly one chosen order/day.
create view public.driver_daily_fuel_costs with (security_barrier=true) as
 select f.id,f.driver_id,f.region_id,f.assignment_id,f.service_date,f.amount,f.reviewed_at
 from public.driver_daily_fuel f where f.status='approved' and public.is_admin();
revoke all on public.driver_daily_fuel_costs from public,anon;
grant select on public.driver_daily_fuel_costs to authenticated;
create function public.record_driver_daily_fuel_event() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 insert into public.driver_daily_fuel_events(fuel_id,actor_id,snapshot) values(new.id,auth.uid(),to_jsonb(new));
 return new;
end; $$;
create trigger driver_daily_fuel_event after insert or update on public.driver_daily_fuel
 for each row execute function public.record_driver_daily_fuel_event();
create function public.driver_daily_fuel_json(f public.driver_daily_fuel) returns jsonb
language sql immutable set search_path='' as $$
 select jsonb_build_object('id',f.id,'date',f.service_date,'assignmentId',f.assignment_id,'version',f.version,'status',f.status,
 'amount',f.amount,'receipts',f.receipts,'reviewNote',f.review_note);
$$;
create function public.has_driver_fuel_day(target_driver uuid,target_region uuid,target_date date) returns boolean
language sql stable security definer set search_path='' as $$
 select target_date<=(now() at time zone 'Asia/Tokyo')::date and exists(
  select 1 from public.driver_assignments a join public.orders o on o.id=a.order_id and o.region_id=a.region_id
  where a.driver_id=target_driver and a.region_id=target_region and a.service_date=target_date and a.status='completed'
  and o.status<>'キャンセル' and a.service_date between o.date and o.end_date and not(a.service_date=any(o.off_dates)));
$$;
create function public.driver_daily_fuel_data(target_month text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare identity record; result jsonb;
begin
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 if target_month is null or target_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then raise exception 'Invalid month' using errcode='22023'; end if;
 select coalesce(jsonb_agg(public.driver_daily_fuel_json(f) order by f.service_date),'[]') into result
 from public.driver_daily_fuel f where f.driver_id=identity.driver_id and f.region_id=identity.region_id
 and to_char(f.service_date,'YYYY-MM')=target_month;
 return result;
end; $$;
create function public.submit_driver_daily_fuel(target_date date,target_assignment uuid,expected_version bigint,target_request uuid,
 amount bigint,receipts jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare identity record; f public.driver_daily_fuel; receipt jsonb; p text; a public.driver_assignments; o public.orders;
begin
 select ord.* into o from public.orders ord join public.driver_assignments x on x.order_id=ord.id
 where x.id=target_assignment for share of ord;
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 perform 1 from public.driver_auth_links where driver_id=identity.driver_id for update;
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 select * into a from public.driver_assignments where id=target_assignment
 and driver_id=identity.driver_id and region_id=identity.region_id for share;
 if not found or a.status<>'completed' or a.service_date is distinct from target_date or o.status='キャンセル'
 or target_date>(now() at time zone 'Asia/Tokyo')::date or target_date<o.date or target_date>o.end_date or target_date=any(o.off_dates) then
  raise exception 'Completed own day required' using errcode='42501'; end if;
 if expected_version is null or expected_version<0 or target_request is null or amount is null
 or amount not between 1 and 99999999999999 or jsonb_typeof(receipts) is distinct from 'array' then
  raise exception 'Invalid fuel submission' using errcode='22023'; end if;
 if jsonb_array_length(receipts)>5 then raise exception 'Too many receipts' using errcode='22023'; end if;
 for receipt in select value from jsonb_array_elements(receipts) loop
  if jsonb_typeof(receipt) is distinct from 'string' then raise exception 'Invalid receipt' using errcode='22023'; end if;
  p:=receipt#>>'{}';
  if p !~ ('^'||auth.uid()::text||'/'||target_date::text||'/[0-9a-f-]{36}\.(jpg|png|webp)$')
  or not exists(select 1 from storage.objects where bucket_id='driver-fuel-receipts' and name=p) then
   raise exception 'Own stored receipt required' using errcode='42501'; end if;
 end loop;
 select * into f from public.driver_daily_fuel where driver_id=identity.driver_id and service_date=target_date for update;
 if f.id is not null and f.request_id=target_request then
  if f.amount<>amount or f.receipts<>receipts or f.assignment_id<>target_assignment then raise exception 'Request key changed' using errcode='40001'; end if;
  return public.driver_daily_fuel_json(f);
 end if;
 if (f.id is null and expected_version<>0) or (f.id is not null and (f.version<>expected_version or f.status<>'rejected')) then
  raise exception 'Daily fuel already submitted or changed' using errcode='40001'; end if;
 insert into public.driver_daily_fuel(driver_id,region_id,service_date,assignment_id,baseline,status,amount,receipts,request_id)
 values(identity.driver_id,identity.region_id,target_date,a.id,
 jsonb_build_object('fuelCost',o.finance_by_date->target_date::text->'fuelCost'),'pending',amount,receipts,target_request)
 on conflict(driver_id,service_date) do update set version=driver_daily_fuel.version+1,status='pending',
 assignment_id=excluded.assignment_id,baseline=excluded.baseline,
 amount=excluded.amount,receipts=excluded.receipts,request_id=excluded.request_id,submitted_at=now(),
 review_note='',reviewed_at=null,reviewed_by=null returning * into f;
 return public.driver_daily_fuel_json(f);
end; $$;
create function public.admin_driver_daily_fuel(target_month text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.is_admin() then raise exception 'Admin required' using errcode='42501'; end if;
 if target_month is null or target_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then raise exception 'Invalid month' using errcode='22023'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('driverName',d.name,'pickup',o.pickup,'destination',o.destination,
 'claim',public.driver_daily_fuel_json(f))
 order by f.service_date,d.name) from public.driver_daily_fuel f join public.drivers d on d.id=f.driver_id
 join public.driver_assignments a on a.id=f.assignment_id join public.orders o on o.id=a.order_id
 where to_char(f.service_date,'YYYY-MM')=target_month),'[]');
end; $$;
create function public.review_driver_daily_fuel(target_fuel uuid,expected_version bigint,decision text,note text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare f public.driver_daily_fuel; a public.driver_assignments; o public.orders; day_finance jsonb; total numeric;
begin
 if not public.is_admin() then raise exception 'Admin required' using errcode='42501'; end if;
 select ord.* into o from public.orders ord join public.driver_assignments x on x.order_id=ord.id
 join public.driver_daily_fuel d on d.assignment_id=x.id where d.id=target_fuel for update of ord;
 select * into f from public.driver_daily_fuel where id=target_fuel for update;
 if not found or f.version is distinct from expected_version or f.status<>'pending' then
  raise exception 'Pending fuel changed' using errcode='40001'; end if;
 if decision is null or decision not in ('approved','rejected') or note is null or length(note)>500
 or (decision='rejected' and length(btrim(note))=0) then raise exception 'Invalid review' using errcode='22023'; end if;
 if decision='approved' then
  select * into a from public.driver_assignments where id=f.assignment_id for share;
  if not found or a.driver_id<>f.driver_id or a.region_id<>f.region_id or a.service_date<>f.service_date
  or a.status<>'completed' or o.status='キャンセル' or f.service_date<o.date or f.service_date>o.end_date
  or f.service_date=any(o.off_dates) then raise exception 'Linked order changed' using errcode='40001'; end if;
  day_finance:=coalesce(o.finance_by_date->f.service_date::text,'{}');
  if jsonb_build_object('fuelCost',day_finance->'fuelCost')<>f.baseline then
   raise exception 'Order fuel cost changed; reject for resubmission' using errcode='40001'; end if;
  total:=coalesce((day_finance->>'fuelCost')::numeric,0)+f.amount;
  if total>99999999999999 then raise exception 'Fuel cost limit exceeded' using errcode='22023'; end if;
  day_finance:=day_finance||jsonb_build_object('fuelCost',total);
  update public.orders set finance_by_date=jsonb_set(coalesce(finance_by_date,'{}'),array[f.service_date::text],day_finance,true)
   where id=o.id;
 end if;
 update public.driver_daily_fuel set status=decision,version=version+1,review_note=btrim(note),
 reviewed_at=now(),reviewed_by=auth.uid() where id=f.id returning * into f;
 return public.driver_daily_fuel_json(f);
end; $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('driver-fuel-receipts','driver-fuel-receipts',false,5242880,array['image/jpeg','image/png','image/webp']);
create function public.can_access_driver_fuel_receipt(path text,writing boolean) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare identity record; day date;
begin
 if path is null or path !~ '^[0-9a-f-]{36}/[0-9]{4}-[0-9]{2}-[0-9]{2}/[0-9a-f-]{36}\.(jpg|png|webp)$' then return false; end if;
 if not writing and public.is_admin() then return true; end if;
 select * into identity from public.driver_identity();
 if not found or split_part(path,'/',1)<>auth.uid()::text then return false; end if;
 begin day:=split_part(path,'/',2)::date; exception when datetime_field_overflow or invalid_datetime_format then return false; end;
 if not writing then
  return public.has_driver_fuel_day(identity.driver_id,identity.region_id,day) or exists(
   select 1 from public.driver_daily_fuel f where f.driver_id=identity.driver_id and f.region_id=identity.region_id
   and f.service_date=day and f.receipts ? path);
 end if;
 return public.has_driver_fuel_day(identity.driver_id,identity.region_id,day) and not exists(
  select 1 from public.driver_daily_fuel f where f.driver_id=identity.driver_id and f.service_date=day and f.status<>'rejected');
end; $$;
create policy driver_fuel_receipt_insert on storage.objects for insert to authenticated
 with check(bucket_id='driver-fuel-receipts' and public.can_access_driver_fuel_receipt(name,true));
create policy driver_fuel_receipt_select on storage.objects for select to authenticated
 using(bucket_id='driver-fuel-receipts' and public.can_access_driver_fuel_receipt(name,false));
revoke all on function public.record_driver_daily_fuel_event(),public.driver_daily_fuel_json(public.driver_daily_fuel),
 public.has_driver_fuel_day(uuid,uuid,date) from public,anon,authenticated;
revoke all on function public.driver_daily_fuel_data(text),public.submit_driver_daily_fuel(date,uuid,bigint,uuid,bigint,jsonb),
 public.admin_driver_daily_fuel(text),public.review_driver_daily_fuel(uuid,bigint,text,text),
 public.can_access_driver_fuel_receipt(text,boolean) from public,anon;
grant execute on function public.driver_daily_fuel_data(text),public.submit_driver_daily_fuel(date,uuid,bigint,uuid,bigint,jsonb),
 public.admin_driver_daily_fuel(text),public.review_driver_daily_fuel(uuid,bigint,text,text),
 public.can_access_driver_fuel_receipt(text,boolean) to authenticated;


-- Source: 022-driver-monthly-shifts.sql; SHA256: fd08cbabbfd0047796df8129aadf2b768b3398470a3db08c5f295f9e6398cdd7
set local lock_timeout='3s';
set local statement_timeout='30s';
create table public.driver_monthly_shifts (
 driver_id uuid not null references public.drivers(id),
 region_id uuid not null references public.regions(id),
 month text not null check(month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
 rest_dates date[] not null default '{}', note text not null default '' check(length(note)<=1000),
 version bigint not null default 1, request_id uuid not null,
 submitted_at timestamptz not null default now(), primary key(driver_id,month)
);
alter table public.driver_monthly_shifts enable row level security;
revoke all on public.driver_monthly_shifts from public,anon,authenticated;
create table public.driver_monthly_shift_events (
 id uuid primary key default gen_random_uuid(), driver_id uuid not null, month text not null,
 actor_id uuid references auth.users(id), occurred_at timestamptz not null default now(), snapshot jsonb not null
);
alter table public.driver_monthly_shift_events enable row level security;
revoke all on public.driver_monthly_shift_events from public,anon,authenticated;
create function public.record_driver_monthly_shift_event() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 insert into public.driver_monthly_shift_events(driver_id,month,actor_id,snapshot)
 values(new.driver_id,new.month,auth.uid(),to_jsonb(new));
 return new;
end; $$;
create trigger driver_monthly_shift_event after insert or update on public.driver_monthly_shifts
 for each row execute function public.record_driver_monthly_shift_event();
create function public.driver_monthly_shift(target_month text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare identity record; result jsonb;
begin
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 if target_month is null or target_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then
  raise exception 'Invalid month' using errcode='22023'; end if;
 select jsonb_build_object('month',f.month,'version',f.version,'dates',to_jsonb(f.rest_dates),'note',f.note) into result
 from public.driver_monthly_shifts f where f.driver_id=identity.driver_id and f.region_id=identity.region_id and f.month=target_month;
 return coalesce(result,jsonb_build_object('month',target_month,'version',0,'dates','[]'::jsonb,'note',''));
end; $$;
create function public.submit_driver_monthly_shift(target_month text,expected_version bigint,target_request uuid,
 rest_dates date[],note text) returns jsonb language plpgsql security definer set search_path='' as $$
declare identity record; f public.driver_monthly_shifts; normalized date[];
begin
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 perform 1 from public.driver_auth_links where driver_id=identity.driver_id for update;
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 if target_month is null or target_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$'
 or expected_version is null or expected_version<0 or target_request is null or rest_dates is null
 or cardinality(rest_dates)>31 or note is null or length(note)>1000 then
  raise exception 'Invalid shift submission' using errcode='22023'; end if;
 if exists(select 1 from unnest(rest_dates) d where d is null or to_char(d,'YYYY-MM')<>target_month)
 or (select count(distinct d) from unnest(rest_dates) d)<>cardinality(rest_dates) then
  raise exception 'Invalid rest dates' using errcode='22023'; end if;
 select coalesce(array_agg(d order by d),'{}'::date[]) into normalized from unnest(rest_dates) d;
 select * into f from public.driver_monthly_shifts where driver_id=identity.driver_id and month=target_month for update;
 if f.driver_id is not null and f.region_id<>identity.region_id then raise exception 'Driver region changed' using errcode='42501'; end if;
 if f.driver_id is not null and f.request_id=target_request then
  if f.rest_dates<>normalized or f.note<>btrim(note) then raise exception 'Request key changed' using errcode='40001'; end if;
  return public.driver_monthly_shift(target_month);
 end if;
 if (f.driver_id is null and expected_version<>0) or (f.driver_id is not null and f.version<>expected_version) then
  raise exception 'Shift changed' using errcode='40001'; end if;
 insert into public.driver_monthly_shifts(driver_id,region_id,month,rest_dates,note,request_id)
 values(identity.driver_id,identity.region_id,target_month,normalized,btrim(note),target_request)
 on conflict(driver_id,month) do update set rest_dates=excluded.rest_dates,note=excluded.note,
 version=driver_monthly_shifts.version+1,request_id=excluded.request_id,submitted_at=now();
 return public.driver_monthly_shift(target_month);
end; $$;
create function public.staff_driver_rest_days(service_dates date[]) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.is_staff() then raise exception 'Staff required' using errcode='42501'; end if;
 if service_dates is null or cardinality(service_dates) not between 1 and 3660
 or array_position(service_dates,null) is not null then raise exception 'Invalid service dates' using errcode='22023'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('driverId',f.driver_id,'date',d) order by f.driver_id,d)
 from public.driver_monthly_shifts f join public.drivers driver on driver.id=f.driver_id and driver.region_id=f.region_id
 cross join lateral unnest(f.rest_dates) d
 where d=any(service_dates) and (public.is_admin() or f.region_id=(select p.region_id from public.profiles p where p.id=auth.uid()))),'[]');
end; $$;
revoke all on function public.record_driver_monthly_shift_event() from public,anon,authenticated;
revoke all on function public.driver_monthly_shift(text),public.submit_driver_monthly_shift(text,bigint,uuid,date[],text),
 public.staff_driver_rest_days(date[]) from public,anon;
grant execute on function public.driver_monthly_shift(text),public.submit_driver_monthly_shift(text,bigint,uuid,date[],text),
 public.staff_driver_rest_days(date[]) to authenticated;


-- Source: 023-driver-login-profile.sql; SHA256: 1537ca10d4feaf2ae76816aca4412b42aeafd734006801d3a22a07a9007060ba
set local lock_timeout='3s';
set local statement_timeout='30s';
create table public.driver_profile_preferences (
 driver_id uuid primary key references public.drivers(id),
 prompted boolean not null default false, version bigint not null default 0,
 updated_at timestamptz not null default now()
);
alter table public.driver_profile_preferences enable row level security;
revoke all on public.driver_profile_preferences from public,anon,authenticated;
create function public.admin_driver_logins() returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.is_admin() then raise exception 'Administrator required' using errcode='42501'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('driverId',l.driver_id,'userId',l.user_id,
 'email',u.email,'status',l.status,'version',l.version) order by l.driver_id)
 from public.driver_auth_links l join auth.users u on u.id=l.user_id),'[]');
end; $$;
create function public.admin_driver_login_target(target_driver uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare d public.drivers; l public.driver_auth_links;
begin
 if not public.is_admin() then raise exception 'Administrator required' using errcode='42501'; end if;
 select * into d from public.drivers where id=target_driver;
 if not found then raise exception 'Driver missing' using errcode='22023'; end if;
 select * into l from public.driver_auth_links where driver_id=d.id;
 return jsonb_build_object('driverId',d.id,'name',d.name,'regionId',d.region_id,
 'userId',l.user_id,'status',l.status,'version',l.version);
end; $$;
create function public.driver_own_profile() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare identity record; result jsonb;
begin
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 select jsonb_build_object('phone',coalesce(d.phone,''),'wechat',coalesce(d.wechat,''),
 'whatsapp',coalesce(d.whatsapp,''),'licenseExpiry',coalesce(d.license_expiry::text,''),
 'prompted',coalesce(p.prompted,false),'version',coalesce(p.version,0)) into result
 from public.drivers d left join public.driver_profile_preferences p on p.driver_id=d.id
 where d.id=identity.driver_id;
 return result;
end; $$;
create function public.update_driver_own_profile(expected_version bigint,action text,contacts jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare identity record; v bigint; p jsonb; expiry date;
begin
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 -- Match existing binding lock order: profile, driver, then identity link.
 perform 1 from public.profiles where id=auth.uid() for update;
 perform 1 from public.drivers where id=identity.driver_id for update;
 perform 1 from public.driver_auth_links where driver_id=identity.driver_id for update;
 select * into identity from public.driver_identity();
 if not found then raise exception 'Driver required' using errcode='42501'; end if;
 select version into v from public.driver_profile_preferences where driver_id=identity.driver_id for update;
 if expected_version is null or coalesce(v,0)<>expected_version then raise exception 'Profile changed' using errcode='40001'; end if;
 if action is null or action not in ('save','skip') or contacts is null then raise exception 'Invalid profile action' using errcode='22023'; end if;
 if action='save' then
  if jsonb_typeof(contacts) is distinct from 'object' or
   (select count(*) from jsonb_object_keys(contacts))<>4 or not(contacts ?& array['phone','wechat','whatsapp','licenseExpiry']) then
   raise exception 'Invalid contacts' using errcode='22023'; end if;
  for p in select value from jsonb_each(contacts) loop
   if jsonb_typeof(p) is distinct from 'string' then raise exception 'Invalid contact type' using errcode='22023'; end if;
  end loop;
  if length(contacts->>'phone')>100 or length(contacts->>'wechat')>200 or length(contacts->>'whatsapp')>200 then
   raise exception 'Contact too long' using errcode='22023'; end if;
  if contacts->>'licenseExpiry'<>'' then
   if contacts->>'licenseExpiry' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid expiry' using errcode='22023'; end if;
   expiry:=(contacts->>'licenseExpiry')::date;
  end if;
  update public.drivers set phone=btrim(contacts->>'phone'),wechat=btrim(contacts->>'wechat'),
   whatsapp=btrim(contacts->>'whatsapp'),license_expiry=expiry where id=identity.driver_id;
 elsif contacts<>'{}'::jsonb then raise exception 'Skip must not update contacts' using errcode='22023';
 end if;
 insert into public.driver_profile_preferences(driver_id,prompted,version) values(identity.driver_id,true,1)
 on conflict(driver_id) do update set prompted=true,version=driver_profile_preferences.version+1,updated_at=now();
 return public.driver_own_profile();
end; $$;
revoke all on function public.admin_driver_logins(),public.admin_driver_login_target(uuid),
 public.driver_own_profile(),public.update_driver_own_profile(bigint,text,jsonb) from public,anon;
grant execute on function public.admin_driver_logins(),public.admin_driver_login_target(uuid),
 public.driver_own_profile(),public.update_driver_own_profile(bigint,text,jsonb) to authenticated;


-- Source: 024-report-order-defaults.sql; SHA256: 17628e953c14f7f926afb3ef98bc160fef8bdfb004cfcba3df4a28ce4be039b1
set local lock_timeout='3s';
set local statement_timeout='20s';
create or replace function public.driver_report_defaults(target_date date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare identity record; result jsonb;
begin
 select * into identity from public.driver_identity();
 if not found then raise exception 'Active driver required' using errcode='42501'; end if;
 if target_date is null then raise exception 'Service date required' using errcode='22023'; end if;
 select jsonb_build_object('serviceDate',target_date,'driverName',d.name,
 'orders',coalesce((
   select jsonb_agg(jsonb_build_object(
     'assignmentId',a.assignment_id,'time',a.departure_time,'pickup',a.pickup,'destination',a.destination,
     'vehicleNumber',coalesce(nullif(v.plate,''),day.plate,''),
     'depot',case when nullif(btrim(c.garage_address),'') is not null then
       jsonb_build_object('name',c.name,'address',btrim(c.garage_address)) else null end
   ) order by a.departure_time,a.assignment_id)
   from public.driver_orders(target_date,null) a
   join public.orders o on o.id=a.order_id and o.region_id=identity.region_id
   cross join lateral (select
     coalesce(o.finance_by_date->target_date::text->>'vehicle',o.vehicle) as vehicle,
     coalesce(o.finance_by_date->target_date::text->>'vehiclePlate',
       to_jsonb(o)->>'vehicle_plate',to_jsonb(o)->>'plate') as plate) day
   left join lateral (
     select matched.* from public.vehicles matched
     where matched.region_id=identity.region_id
       and case when coalesce(day.plate,'')<>'' then matched.plate=day.plate else matched.name=day.vehicle end
       and (select count(*) from public.vehicles other where other.region_id=identity.region_id
         and case when coalesce(day.plate,'')<>'' then other.plate=day.plate else other.name=day.vehicle end)=1
   ) v on true
   left join lateral (
     select matched.* from public.companies matched
     where matched.region_id=identity.region_id and matched.name=v.owner_company
       and (select count(*) from public.companies other
         where other.region_id=identity.region_id and other.name=v.owner_company)=1
   ) c on true
 ),'[]'::jsonb)) into result
 from public.drivers d where d.id=identity.driver_id and d.region_id=identity.region_id;
 return result;
end;
$$;
revoke all on function public.driver_report_defaults(date) from public,anon;
grant execute on function public.driver_report_defaults(date) to authenticated;


-- Source: 025-order-approved-receipts.sql; SHA256: c92c55713459948ae83f82901d5a1438fdd5a5dba57e32651b1e9b07e3e958e2
set local lock_timeout='3s';
set local statement_timeout='20s';
create function public.staff_order_receipts(target_order uuid,target_date date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 if not public.is_staff() or not exists(select 1 from public.orders o where o.id=target_order
   and (public.is_admin() or o.region_id=(select p.region_id from public.profiles p where p.id=auth.uid()))) then
   raise exception 'Staff order access required' using errcode='42501'; end if;
 if target_date is null then raise exception 'Service date required' using errcode='22023'; end if;
 select coalesce(jsonb_agg(x.receipt order by x.category,x.path),'[]'::jsonb) into result from (
   select c.category,p.path,jsonb_build_object('bucket','driver-finance-receipts',
     'path',p.path,'category',c.category,'detail',e.item->>'detail') receipt
   from public.driver_finance_claims c
   join public.driver_assignments a on a.id=c.assignment_id and a.region_id=c.region_id and a.driver_id=c.driver_id
   cross join lateral jsonb_array_elements(c.expenses) e(item)
   cross join lateral jsonb_array_elements_text(e.item->'receipts') p(path)
   where a.order_id=target_order and a.service_date=target_date and c.status='approved' and c.category in ('company','trip')
   union all
   select 'fuel',p.path,jsonb_build_object('bucket','driver-fuel-receipts',
     'path',p.path,'category','fuel','detail','燃油费')
   from public.driver_daily_fuel f
   join public.driver_assignments a on a.id=f.assignment_id and a.region_id=f.region_id and a.driver_id=f.driver_id
   cross join lateral jsonb_array_elements_text(f.receipts) p(path)
   where a.order_id=target_order and a.service_date=target_date and f.service_date=target_date and f.status='approved'
 ) x;
 return result;
end;
$$;
create function public.can_read_approved_order_receipt(target_bucket text,target_path text) returns boolean
language sql stable security definer set search_path='' as $$
 select public.is_staff() and exists(
   select 1 from (
     select a.region_id from public.driver_finance_claims c
     join public.driver_assignments a on a.id=c.assignment_id and a.region_id=c.region_id and a.driver_id=c.driver_id
     join public.orders o on o.id=a.order_id and o.region_id=a.region_id
     cross join lateral jsonb_array_elements(c.expenses) e(item)
     where target_bucket='driver-finance-receipts' and c.status='approved' and c.category in ('company','trip')
       and e.item->'receipts' ? target_path
     union all
     select a.region_id from public.driver_daily_fuel f
     join public.driver_assignments a on a.id=f.assignment_id and a.region_id=f.region_id and a.driver_id=f.driver_id
     join public.orders o on o.id=a.order_id and o.region_id=a.region_id
     where target_bucket='driver-fuel-receipts' and f.status='approved' and f.receipts ? target_path
   ) allowed where public.is_admin()
     or allowed.region_id=(select p.region_id from public.profiles p where p.id=auth.uid()));
$$;
create policy staff_approved_order_receipt_select on storage.objects for select to authenticated
 using(bucket_id in ('driver-finance-receipts','driver-fuel-receipts')
   and public.can_read_approved_order_receipt(bucket_id,name));
revoke all on function public.staff_order_receipts(uuid,date),
 public.can_read_approved_order_receipt(text,text) from public,anon;
grant execute on function public.staff_order_receipts(uuid,date),
 public.can_read_approved_order_receipt(text,text) to authenticated;


-- Source: 026-order-finance-pending.sql; SHA256: 97970ee09b85ccd0cb7f9af4724be8c5fabff7fc5ee42d1ce6973c8344e7e37a
set local lock_timeout='3s';
set local statement_timeout='20s';
create function public.admin_order_finance_pending(target_month text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 if not public.is_admin() then raise exception 'Administrator required' using errcode='42501'; end if;
 if target_month is null or target_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then
 raise exception 'Invalid month' using errcode='22023'; end if;
 select coalesce(jsonb_agg(x.item order by x.service_date,x.order_id,x.kind,x.category),'[]'::jsonb) into result from (
   select a.service_date,a.order_id,'finance' kind,c.category,
     jsonb_build_object('kind','finance','orderId',a.order_id,'date',a.service_date,'driverName',d.name,
       'claim',public.driver_finance_claim_json(c)) item
   from public.driver_finance_claims c
   join public.driver_assignments a on a.id=c.assignment_id and a.driver_id=c.driver_id and a.region_id=c.region_id
   join public.drivers d on d.id=c.driver_id and d.region_id=c.region_id
   where c.status='pending' and to_char(a.service_date,'YYYY-MM')=target_month
   union all
   select f.service_date,a.order_id,'fuel','fuel',
     jsonb_build_object('kind','fuel','orderId',a.order_id,'date',f.service_date,'driverName',d.name,
       'claim',public.driver_daily_fuel_json(f))
   from public.driver_daily_fuel f
   join public.driver_assignments a on a.id=f.assignment_id and a.driver_id=f.driver_id
     and a.region_id=f.region_id and a.service_date=f.service_date
   join public.drivers d on d.id=f.driver_id and d.region_id=f.region_id
   where f.status='pending' and to_char(f.service_date,'YYYY-MM')=target_month
 ) x;
 return result;
end;
$$;
revoke all on function public.admin_order_finance_pending(text) from public,anon;
grant execute on function public.admin_order_finance_pending(text) to authenticated;


-- Source: 027-driver-execution-status.sql; SHA256: 191f5243dd75ad6cf4b774cb4797048447b0c135c7e36334111d6a9d946b6457
set local lock_timeout='3s';
set local statement_timeout='20s';
create function public.staff_driver_execution_status() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare day date:=(now() at time zone 'Asia/Tokyo')::date; result jsonb;
begin
 if not public.is_staff() then raise exception 'Staff required' using errcode='42501'; end if;
 select jsonb_build_object('date',day,'rows',coalesce(jsonb_agg(
   jsonb_build_object('orderId',a.order_id,'date',a.service_date,'status',a.status,'version',a.version)
   order by a.order_id),'[]'::jsonb)) into result
 from public.driver_assignments a
 join public.orders o on o.id=a.order_id and o.region_id=a.region_id
 where a.service_date=day and a.status in ('assigned','acknowledged','en_route','arrived','in_service')
   and o.status<>'キャンセル' and day between o.date and o.end_date and not(day=any(o.off_dates))
   and (public.is_admin() or a.region_id=(select p.region_id from public.profiles p where p.id=auth.uid()));
 return result;
end;
$$;
revoke all on function public.staff_driver_execution_status() from public,anon;
grant execute on function public.staff_driver_execution_status() to authenticated;


